using System.Diagnostics;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using Naide.LevelManager.Application;
using Naide.LevelManager.Domain;
using Naide.LevelManager.Infrastructure;
internal static class OnlineScaleBenchmark
{
 public static async Task<int> Run(string[] args)
 {
  string Option(string key){var index=Array.IndexOf(args,key);return index>=0&&index+1<args.Length?args[index+1]:throw new ArgumentException("缺少参数 "+key);}var original=Option("--source");var output=Option("--output");if(!Path.IsPathFullyQualified(original)||!File.Exists(original)||!Path.IsPathFullyQualified(output)||Directory.Exists(output))throw new ArgumentException("请使用现有容量样本及新的绝对输出目录");Directory.CreateDirectory(output);var total=Stopwatch.StartNew();var source=Path.Combine(output,"isolated-source.db");var size=new FileInfo(original).Length;if(new DriveInfo(Path.GetPathRoot(output)!).AvailableFreeSpace<size*3+1024L*1024*1024)throw new IOException("规模验证空间不足");Console.WriteLine("cloning finished capacity sample, original evidence stays unchanged");File.Copy(original,source);var store=new SqliteConfigurationStore(source);await store.InitializeAsync(allowCapacityProfile:true);await using(var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=source,Pooling=false}.ToString())){await db.OpenAsync();await using var check=db.CreateCommand();check.CommandText="SELECT Value FROM database_properties WHERE Key='profile'";if(Convert.ToString(await check.ExecuteScalarAsync())!="capacity-test")throw new InvalidOperationException("仅允许隔离容量样本，不接受真实业务库");}
  var config=await store.GetAsync();var history=new SqliteHistoryStore(source);var initial=(await history.StatisticsAsync()).Rows;var copied=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var readTimes=new List<double>();var writeTimes=new List<double>();var writing=true;var epoch=Guid.NewGuid();var at=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();var from=DateTimeOffset.Parse("2025-01-01T00:00:00Z").ToUnixTimeMilliseconds();var until=from+365L*86400000;
  var writer=Task.Run(async()=>{await copied.Task;try{for(var n=0;n<100;n++){var watch=Stopwatch.StartNew();await history.AppendAsync(config.Tanks.Select(t=>new HistorySample{TankId=t.Id,AtUtcMs=at+n*60000L,ReceivedAtUtcMs=at+n*60000L,ConfigurationRevision=config.Revision,CalculationRevision=1,AcquisitionSessionId=epoch,LevelMm=Measurement.Good(5000),InstantTemperatureC=Measurement.Good(0),InstrumentDensityKgM3=Measurement.Good(832),CurrentVolumeM3=Measurement.Good(2000),NetVolumeM3=Measurement.Good(1990),MassT=Measurement.Good(1655.68m),Pressure1KPa=Measurement.Good(25),Pressure2KPa=Measurement.Good(50),Analog1Ma=Measurement.Good(12),Analog2Ma=Measurement.Good(16),AtsPoints=Enumerable.Range(1,16).Select(i=>new TemperaturePoint(i,Measurement.Good(i))).ToArray()}).ToArray());writeTimes.Add(watch.Elapsed.TotalMilliseconds);await Task.Delay(200);}}finally{writing=false;}});
  var queries=Task.Run(async()=>{await copied.Task;while(writing){var watch=Stopwatch.StartNew();await history.QueryAsync(new(from,until,config.Tanks[readTimes.Count%config.Tanks.Count].Id,Limit:500));readTimes.Add(watch.Elapsed.TotalMilliseconds);await Task.Delay(20);}});
  var backupWatch=Stopwatch.StartNew();Console.WriteLine("incremental backup with concurrent full 128-tank writes and queries");var backup=Path.Combine(output,"incremental-backup.db");var result=await OnlineDatabaseBackup.CreateAsync(source,backup,_=>{copied.TrySetResult();return Task.CompletedTask;},allowCapacityProfile:true);await Task.WhenAll(writer,queries);var backupSeconds=backupWatch.Elapsed.TotalSeconds;var restoredRows=(await new SqliteHistoryStore(backup).StatisticsAsync()).Rows;if(restoredRows!=initial)throw new InvalidDataException("在线备份未保留第一步读取时的一致快照");if((await history.StatisticsAsync()).Rows!=initial+100L*config.Tanks.Count)throw new InvalidDataException("备份期间并发归档有丢失");
  await File.WriteAllTextAsync(Path.Combine(output,"backup-verification.json"),JsonSerializer.Serialize(new{passed=true,schemaVersion=SqliteConfigurationStore.CurrentSchema,initialRows=initial,snapshotRows=restoredRows,concurrentWrittenRows=config.Tanks.Count*100,concurrentWrites=writeTimes.Count,writeMaxMs=writeTimes.Max(),queryCount=readTimes.Count,queryMaxMs=readTimes.Max(),backupSeconds,result.Bytes,result.Sha256,realDeviceAccess=false},new JsonSerializerOptions{WriteIndented=true}));
  Console.WriteLine("annual single-tank real Excel with all 16 ATS points and quality states");var excelWatch=Stopwatch.StartNew();var excel=await new HistoryExcelExporter(history).ExportAsync(Path.Combine(output,"excel"),new(from,until,config.Tanks[0].Id,true),config);if(excel.Rows!=525600)throw new InvalidDataException("单罐全年Excel行数不一致");var summary=new{passed=true,schemaVersion=SqliteConfigurationStore.CurrentSchema,initialRows=initial,snapshotRows=restoredRows,concurrentWrittenRows=config.Tanks.Count*100,concurrentWrites=writeTimes.Count,writeMaxMs=writeTimes.Max(),writeAverageMs=writeTimes.Average(),queryCount=readTimes.Count,queryMaxMs=readTimes.Max(),backupSeconds,result.Bytes,result.Sha256,annualExcel=excel,excelSeconds=excelWatch.Elapsed.TotalSeconds,elapsedSeconds=total.Elapsed.TotalSeconds,peakProcessBytes=Process.GetCurrentProcess().PeakWorkingSet64,realDeviceAccess=false,limitation="隔离复制当前结构的合成数据，不代替现场设备、Windows10或72小时可靠性试验"};await File.WriteAllTextAsync(Path.Combine(output,"result.json"),JsonSerializer.Serialize(summary,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS: final-scale incremental consistent backup, live writes/queries, actual annual Excel");return 0;
 }
}
